  async getDetail(x: uploadMasterMDL) {

    x.isLoading = true;
    x.isExpanded = !x.isExpanded;
    if (x.isExpanded && !x.files.length) { //&& !x.isLive
      x.files = [];
      let res = await this.us.fetchReportDetail(x.nUPid);
      if (res) {
        x.files.push(...res); // = [...res] //
      }
    }
  }


