  onDateChange(event: any): void {

    let objs = { key: 'date', value: this.dateTZ(event) };
    this.date[this.date.length - 1] = objs;
    this.onChange('cDate', { value: objs });
    // Handle the change event here
  }


  checkValueClear(target: any) {
    if (!target.value) {

      if (this.isSearched) {
        this.onChange('cSearch', { value: null })
        this.isSearched = false;
      } else {
        this.appliedFilter['cSearch'] = null;
      }
    }
  }

  onChange(flag, e) {

    this.isSearched = true;
    this.appliedFilter[flag] = e.value;
    this.appliedFilter = { ...this.appliedFilter };

    this.checlForFilter()

    if (flag == 'cDate') {
      // this.fetchHistory();
    }
  }



  checlForFilter() {

    this.isFilter = true;
    let lastIndex = this.summaryFiles.map(item => item.isLive).lastIndexOf(true); // this.summaryFiles.findIndex(e => e.isLive);
    this.summaryFiles.splice(lastIndex + 1, (this.summaryFiles.length - lastIndex))
    // this.summaryFiles.map(a => a.isExpanded = false);
    if (this.isUser) {
      this.appliedFilter.nSectionid = this.nSectionid;
    }
    this.store.fetchHistory(this.appliedFilter);

  }

  clearFilter(flag) {
    if (flag == 'cAction') {
      this.appliedFilter[flag] = this.action[0];
    } else if (flag == 'cDate') {
      this.appliedFilter[flag] = this.date[0];
    } else if (flag == 'cStatus') {
      this.appliedFilter[flag] = this.status[0];
    } else if (flag == 'cFormat') {
      this.appliedFilter[flag] = this.format[0];
    }
    this.appliedFilter = { ...this.appliedFilter };

    this.checlForFilter()

  }



  OnSelection(event: any) {
    event.forEach(a => {
      let ind = this.selectedFiles.findIndex(b => b == (a[0]));
      if (a[1]) {
        if (ind == -1) {
          this.selectedFiles.push((a[0]));
        }
      } else {
        if (ind != -1) {
          this.selectedFiles.splice(ind, 1);
        }
      }
    })
  }



