  onFilters(e, x) {
    if (e > 0) {
      x.isHidden = false;
    } else {
      x.isHidden = true;
    }
    this.cdr.detectChanges();
  }


  isFilters() {
    if (this.appliedFilter.cAction && this.appliedFilter.cAction?.value) {
      return true;
    }
    else if (this.appliedFilter.cDate && this.appliedFilter.cDate?.value) {
      return true;
    }
    else if (this.appliedFilter.cStatus && this.appliedFilter.cStatus?.value) {
      return true;
    }
    else if (this.appliedFilter.cFormat && this.appliedFilter.cFormat?.value) {
      return true;
    }
    else if (this.appliedFilter.cSearch) {
      return true;
    }
    else {
      return false;
    }
  }

