import { AfterViewChecked, Component, EventEmitter, Input, OnChanges, Output, SimpleChanges, ViewChild } from '@angular/core';
import { MatInputModule } from '@angular/material/input';
import { MatPaginator, MatPaginatorModule } from '@angular/material/paginator';
import { MatSort, MatSortModule } from '@angular/material/sort';
import { MatTable, MatTableDataSource, MatTableModule } from '@angular/material/table';
import { fileUploadMDL, reportDetailMDL, uploadAppliedFilters } from '../../../interfaces/upload.interface';
import { environment } from '../../../../../environments/environment';
import { SelectionModel } from '@angular/cdk/collections';
import { UploadManagementService } from '../../../services/upload/upload-management/upload-management.service';
import { CommonModule } from '@angular/common';
import { BytesPipe } from '../../../../shared/pips/bytes/bytes.pipe';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { FormsModule } from '@angular/forms';
interface FileData {
  cFilename: string;
  cStatus: string;
  file: { size: string };
  nProgress?: number;
}
@Component({
  selector: 'history',
  standalone: true,
  imports: [MatInputModule, MatTableModule, FormsModule, MatSortModule, MatPaginatorModule, CommonModule, BytesPipe, MatCheckboxModule],
  templateUrl: './history.component.html',
  styleUrl: './history.component.scss'
})
export class HistoryComponent implements OnChanges, AfterViewChecked {

  @ViewChild('myTable') table: MatTable<any>;

  @Input() filterdata: uploadAppliedFilters;
  displayedColumns: string[] = ['select', 'name', 'status', 'kind', 'size'];
  dataSource: MatTableDataSource<reportDetailMDL>;


  @ViewChild(MatPaginator) paginator: MatPaginator;
  @ViewChild(MatSort) sort: MatSort;

  @Input() data: reportDetailMDL[] = [];
  isloading: boolean = true;

  public allSelected: boolean = false;
  private docIconPath: string = environment.iconpath_doc;

  @Output() onSelection = new EventEmitter<any>();
  constructor(private uploadManage: UploadManagementService) {

  }


  
  applyFilter(filtes) {
    this.dataSource.filter = filtes;
  }
  // applyFilter(event: Event) {
  //   const filterValue = (event.target as HTMLInputElement).value;
  //   this.dataSource.filter = filterValue.trim().toLowerCase();
  //   if (this.dataSource.paginator) {
  //     this.dataSource.paginator.firstPage();
  //   }
  // }



  ngAfterViewChecked() {
    if (this.dataSource && this.dataSource.data.length > 0 && this.isloading) {
      this.isloading = false;
    }
  }
  
  ngAfterViewInit() {
    // this.dataSource = new MatTableDataSource(this.data);

    // this.isloading = false;
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
  }

  ngOnInit(): void {

    this.dataSource = new MatTableDataSource(this.data);


    this.dataSource.filterPredicate = (data: any, filter: any) => {
      const { cAction, cStatus, cFormat, cSearch } = filter["currentValue"];
      try {
        // Check cAction filter
        if (cAction?.value && data.cStatus !== cAction.value) {
          return false;
        }

        // Check cStatus filter
        if (cStatus?.value && data.cStatus !== cStatus.value) {
          return false;
        }

        // Check cFormat filter
        if (cFormat?.value && !cFormat.value.includes(data.filetype || data.cType)) {
          return false;
        }
        if (cSearch && data.cName.toLowerCase().indexOf(cSearch.toLowerCase()) === -1) {
          return false;
        }
      } catch (error) {

      }



      return true;
      // return (!cAction?.value || data.cStatus === cAction.value) &&
      //   (!cStatus?.value || data.cStatus === cStatus.value) &&
      //   (!cFormat?.value || cFormat.value.includes(data.filetype));
      // return (filter["currentValue"].cAction.value ? data.cStatus == filter["currentValue"].cAction.value : true) &&(filter["currentValue"].cStatus.value ? data.cStatus == filter["currentValue"].cStatus.value : true) && (filter["currentValue"].cFormat.value ? filter["currentValue"].cFormat.value.includes(data.filetype) : true);
    };
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['filterdata'] && !changes['filterdata'].firstChange) {
      this.applyFilter(changes['filterdata']);
    }
    if (changes['data'] && !changes['data'].firstChange) {
      this.dataSource.data = changes['data'].currentValue;
    }
  }


  istextTruncated(el) {
    return el.scrollWidth > el.clientWidth;
  }






  bindIcon(node) {
    try {
      const fileType = node.file.name.split('.').pop().toLowerCase();
      return `${this.docIconPath}${fileType}.svg`;
    } catch (error) {
      return `${this.docIconPath}other.svg`;
    }
  }

  pauseUploading(x) {
    x.cStatus = 'PSD';
    this.uploadManage.pauseUpload(x);
  }


  resumeUploading(x) {
    x.cStatus = 'I';
    this.uploadManage.resumeUpload(x);
  }


  OnAllChange() {
    this.data.map(a => a.isChecked = this.allSelected);
    let values = this.data.map(({ isChecked, nUDid }) => ([nUDid, isChecked]))
    this.onSelection.emit(values);
  }


  onSelect(row) {
    if (this.data.findIndex(a => !a.isChecked) > -1) {
      this.allSelected = false;
    } else {
      this.allSelected = true;
    }
    this.onSelection.emit([[row.nUDid, row.isChecked]]);
  }

}
